{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Encainide, the highest-transfer analogue (0.9897), has a measured absolute oral bioavailability of 32±7% in normal subjects, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "AZD0837 (transfer 0.9887) has a mean absolute oral bioavailability of 22–55% in healthy volunteers, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "The praziquantel analogue (transfer 0.9887) shows 27.2±5.4% oral bioavailability in patients, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Asciminib (transfer 0.9886) has an absolute oral bioavailability of approximately 73% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Delavirdine (transfer 0.9884) has an oral bioavailability of 85% in patients with HIV infection, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib (transfer 0.9879) has a geometric mean absolute bioavailability of 25.3% in healthy subjects, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Compound 5 (transfer 0.9877) has a predicted human oral bioavailability of 41%, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "MMV367 (transfer 0.9875) has an estimated human bioavailability of 90%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Pradigastat (transfer 0.9875) was judged completely bioavailable after oral dosing in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Maraviroc (transfer 0.9874) has an oral bioavailability of 33% in healthy volunteers, supporting F≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show human oral bioavailability values ≥20% (mostly 25–90%), directly supporting a high F≥20% prediction. The physicochemical prior suggesting low F is an uncertain prior and is overridden by this consistent experimental evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic study on the exact query molecule; prediction relies on high-transfer analogues.",
    "The query's very high molecular weight and TPSA are not represented by any analogue with measured low F, leaving residual uncertainty about absorption.",
    "Some analogue values are estimates or ranges rather than definitive single measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

